// The index service (browse-scale D2/D4): the RAM read model's lifecycle
// owner. It builds once at boot over the cmd-built Deps closures, detects
// naming-config drift through a two-part scalar epoch, takes wake pokes
// through a coalescing channel, and reconciles on the 60 s janitor tick —
// a watermark walk over content-row updates plus an orphan sweep (re-
// identify mints new ids). Serving is the honesty backstop (D3): ids and
// counted facet values only — every display byte is composed live
// api-side, so a stale index can degrade recall but never falsify a name.

package browse

import (
	"encoding/json"
	"sync"
)

// Epoch is the two-part scalar freshness stamp (D4, reviewer Q3), recomputed
// per reconcile tick from cheap scalar reads (the LibrarySummary
// COUNT/MAX shape, store/libraries.go). Both legs compare for inequality
// only — the epoch is a stamp, never a clock.
type Epoch struct {
	// UpdatedAt is the max updated_at over the NAMING-CONFIG horizon: the
	// rows a config write touches (library rows, prefs, module configs,
	// title overrides) — the leg that trips on naming-config drift. The
	// store keeps updated_at as RFC3339 TEXT, so the max is the verbatim
	// scalar read. A content-row update (an enrichment merge bumps an
	// item's updated_at) trips NEITHER leg by contract — that is the
	// watermark walk's input, caught incrementally instead of paying a
	// full recomposition.
	UpdatedAt string

	// Rows is the indexed corpus row count — the leg that trips on scan
	// adds and deletes (reviewer Q3: a delete bumps no updated_at, so the
	// count leg is what makes deletes converge).
	Rows int64
}

// Deps are the cmd-built closures the service reads the world through —
// the package imports nothing internal (D2), so every store read and the
// naming composition arrive pre-built at the composition root (the
// enrich.Deps posture, wired flat in cmd/mellifera). Every field is
// nil-safe: a nil closure floors (no drift check, idle walk, no sweep, no
// facet recompute) rather than panics — the never-wired posture the
// package's other floors follow.
type Deps struct {
	// Epoch reads the two-part freshness stamp (see Epoch). Drift on
	// either leg means a config write or a corpus add/delete — the
	// reconcile pass answers with a full rebuild.
	Epoch func() Epoch

	// Corpus reads the whole indexed corpus for the boot build and every
	// drift rebuild: the composed search entries (the cmd-side composer
	// runs naming.Namer per entity — Entry is its output shape), the raw
	// series documents per library id the facet aggregates count over,
	// and the content watermark — the max updated_at across the indexed
	// rows — seeding the reconcile walk.
	Corpus func() (entries []Entry, facetDocs map[string][]json.RawMessage, watermark string)

	// Changed walks the content rows updated after the watermark: the
	// fresh entries for exactly those rows (composed by the same cmd-side
	// composer Corpus uses) plus the advanced watermark. This is the
	// incremental path enrichment merges arrive on.
	Changed func(after string) (entries []Entry, watermark string)

	// LiveIDs reads the corpus's current id set — the orphan sweep drops
	// indexed entries absent from it. Re-identify mints a new id, so the
	// old entry's id simply stops being live; a plain delete trips the
	// epoch's count leg first and takes the rebuild path.
	LiveIDs func() map[string]bool

	// Resolver is the About projection bound per library — naming.Namer.
	// MetadataFor wrapped with each library's namer (OQ2: the SAME
	// resolver the About block serves, so facets can never grow a second
	// walk). buildFacets runs it per series document at rebuild time.
	Resolver func(libraryID string, raw json.RawMessage) map[string]any

	// FacetDocs reads one library's raw series documents — the targeted
	// facet recompute after a reconcile walk touches that library (an
	// enrichment merge changes facts as well as names). Nil for a library
	// with no series documents (photo libraries — honest absence).
	FacetDocs func(libraryID string) []json.RawMessage
}

// Service owns the RAM read model: the search index, the per-library
// facet aggregates, and the freshness state (epoch + watermark) they
// reconcile under. Construct with NewService; the zero value is not
// usable. Serving methods are safe for concurrent use — a rebuild or
// reconcile swaps the whole model under the lock (SearchIndex is
// read-only after construction), so a pass never blocks a query longer
// than one pointer swap, and the never-built floor answers empty.
type Service struct {
	deps      Deps
	wake      chan struct{}
	mu        sync.RWMutex
	index     *SearchIndex
	entries   []Entry
	facets    map[string][]Facet
	epoch     Epoch
	watermark string
}

// NewService builds a service over the supplied closures, with the wake
// channel buffered at one — the janitor wake idiom: a burst of pokes
// coalesces into a single pending pass (cmd/mellifera/janitor.go).
func NewService(deps Deps) *Service {
	return &Service{deps: deps, wake: make(chan struct{}, 1)}
}

// Build rebuilds the whole read model from Deps.Corpus — the boot-warm
// path (the janitor boot-run, synchronous pre-serve) and the drift
// path's shared body. A nil Corpus floors to an empty model: search
// answers empty, facets are honestly absent everywhere.
func (s *Service) Build() {
	entries, docs, wm := []Entry(nil), map[string][]json.RawMessage(nil), ""
	if s.deps.Corpus != nil {
		entries, docs, wm = s.deps.Corpus()
	}
	ix := NewSearchIndex(entries)
	facets := buildFacets(s.deps.Resolver, docs)
	e := Epoch{}
	if s.deps.Epoch != nil {
		e = s.deps.Epoch()
	}
	s.mu.Lock()
	s.index, s.entries, s.facets, s.epoch, s.watermark = ix, entries, facets, e, wm
	s.mu.Unlock()
}

// Reconcile runs one reconcile pass — the 60 s janitor tick's body, and
// what a wake poke triggers immediately. The epoch is recomputed first:
// drift on either leg means a naming-config write or a corpus add/delete,
// and the pass is a full Build. Otherwise the watermark walk picks up the
// content rows changed since the last pass and the orphan sweep drops
// entries whose ids stopped being live; the index is rebuilt over the
// spliced entry set (slice rebuild — the composition already paid is
// reused verbatim), and the facet aggregates are recomputed for exactly
// the libraries the walk touched (an enrichment merge changes facts as
// well as names). Two passes racing (tick + poke) walk from the same
// watermark and converge on the same model — the swap is
// last-writer-wins.
func (s *Service) Reconcile() {
	s.mu.RLock()
	built, epoch, entries, facets, watermark := s.index != nil, s.epoch, s.entries, s.facets, s.watermark
	s.mu.RUnlock()

	if !built {
		s.Build() // never warmed — a reconcile before the boot build is just a build
		return
	}
	if s.deps.Epoch != nil {
		if now := s.deps.Epoch(); now != epoch {
			s.Build() // drift ⇒ full rebuild (D4: config writes, corpus adds/deletes)
			return
		}
	}

	// Walk + sweep off the lock: the closures hit the store, serving
	// keeps answering from the current model.
	var changed []Entry
	if s.deps.Changed != nil {
		changed, watermark = s.deps.Changed(watermark)
	}
	var live map[string]bool
	if s.deps.LiveIDs != nil {
		live = s.deps.LiveIDs()
	}
	replaced := make(map[string]bool, len(changed))
	for _, e := range changed {
		replaced[e.ID] = true
	}
	next := make([]Entry, 0, len(entries)+len(changed))
	for _, e := range entries {
		if replaced[e.ID] {
			continue // the walk's fresh entry replaces the stale one
		}
		if live != nil && !live[e.ID] {
			continue // orphan sweep: re-identify mints new ids
		}
		next = append(next, e)
	}
	next = append(next, changed...)

	// Targeted facet recompute for the touched libraries, merged into a
	// NEW map — the old map's slices may still be in a concurrent
	// server's hands, so nothing already published is mutated.
	reFacets := map[string][]Facet{}
	if len(changed) > 0 && s.deps.FacetDocs != nil {
		libs := map[string]bool{}
		for _, e := range changed {
			libs[e.LibraryID] = true
		}
		for lib := range libs {
			reFacets[lib] = countLibraryFacets(s.deps.Resolver, lib, s.deps.FacetDocs(lib))
		}
	}
	merged := make(map[string][]Facet, len(facets)+len(reFacets))
	for lib, fs := range facets {
		merged[lib] = fs
	}
	for lib, fs := range reFacets {
		merged[lib] = fs
	}

	s.mu.Lock()
	s.index, s.entries, s.facets, s.watermark = NewSearchIndex(next), next, merged, watermark
	s.mu.Unlock()
}

// Wake pokes one reconcile pass, coalescing: the channel is buffered at
// one and the send is non-blocking, so a burst of pokes collapses into a
// single pending pass. Never blocks the poke site (a title-override
// handler, a scan-completion fan-out) and never panics racing shutdown.
func (s *Service) Wake() {
	select {
	case s.wake <- struct{}{}:
	default:
	}
}

// WakeChan is the wake channel's receive side — the janitor task's wake
// field (a receive runs one pass beside the interval ticker;
// cmd/mellifera/janitor.go). Never closed: the loop exits on ctx.Done.
func (s *Service) WakeChan() <-chan struct{} { return s.wake }

// Search answers one query against the current index — ids only (D3):
// the handler maps them to live rows and composes every display byte
// fresh. Before the first build it answers empty, never nil slices.
func (s *Service) Search(query string) Hits {
	s.mu.RLock()
	ix := s.index
	s.mu.RUnlock()
	if ix == nil {
		ix = NewSearchIndex(nil)
	}
	return ix.Search(query)
}

// Facets serves one library's facet aggregates. The returned slice is
// the read-only built value served verbatim — never mutated after
// construction — so no per-request copy is paid. A library with no
// aggregates (unknown id, photo library, nothing resolved) is an empty
// non-nil list: the facet keys honestly absent.
func (s *Service) Facets(libraryID string) []Facet {
	s.mu.RLock()
	fs := s.facets[libraryID]
	s.mu.RUnlock()
	if fs == nil {
		return []Facet{}
	}
	return fs
}
